"""Write the static JSON contract consumed by the web app, plus its TypeScript types."""

from __future__ import annotations

import gzip
import json
from pathlib import Path
from typing import Any

import numpy as np
from numpy.typing import NDArray

from clps.config import Site
from clps.horizon import HorizonMask
from clps.observation import Observation
from clps.visibility import Summary, Window

CONTRACT_TS = """\
// Generated by pipeline/src/clps/export.py. Do not edit by hand.
// All times are ISO-8601 UTC; all angles are degrees.

export interface SiteInfo {
  id: string
  name: string
  lat: number
  lon: number
  source_url: string
  group: string
  // Ground slope at the site, measured over this distance. Missing on custom points.
  slope?: { deg: number; baseline_m: number; err_deg?: number }
  // Half-width of the map of nearby ground (m), for sites that have one.
  nearby_half_m?: number
}

export interface HorizonPoint {
  az: number
  el: number
}

export interface TrackPoint {
  t: string
  sun_az: number
  sun_el: number
  sun_frac: number
  sun_up: boolean
  earth_az: number
  earth_el: number
  earth_up: boolean
  sun_vec_me: [number, number, number]
}

export interface TimeWindow {
  start: string
  end: string
}

export interface Summary {
  range: { start: string; end: string; step_h: number }
  obs_height_m: number
  pct_sun: number
  pct_earth: number
  pct_both: number
  max_sun_gap_h: number
  max_earth_gap_h: number
  sun_windows: TimeWindow[]
  earth_windows: TimeWindow[]
}

export interface BandAccuracy {
  min_abs_lat: number
  max_abs_lat: number
  n: number
  sun_median_error: number
  sun_p90_error: number
  earth_median_error: number
  earth_p90_error: number
  hours_agree_median_pct: number
  hours_agree_p10_pct: number
}

// Files for computing custom coordinates in the browser.
export interface CustomMeta {
  ppd: number
  rows: number
  cols: number
  // The span of the ephemeris files, `ephemeris-<year>.bin`, one per calendar year (see DataRange).
  start: string
  hours: number
  obs_height_m: number
  max_abs_lat: number
  near_polar_m: number
  near_global_m: number
  polar: {
    half_m: number
    res_m: number
    size: number
    tile_px: number
    quant_m: number
    far_res_m: number
    far_size: number
  }
  global: {
    res_m: number
    lines: number
    samples: number
    tile_px: number
    scale: number
    pix_per_deg: number
    center_lon: number
    line_offset: number
    sample_offset: number
  }
  model_error: { sun_rmse: number; sun_any_rmse: number; earth_rmse: number }
  bands: BandAccuracy[]
  polar_ridges: BandAccuracy
}

export interface MapMeta {
  moon: { width: number; height: number }
  pole: { width: number; height: number; half_width_m: number }
}

export interface MoonName {
  name: string
  kind: 'mare' | 'crater' | 'valley' | 'mountains'
  lat: number
  lon: number
  diameter_km: number
  source_url: string
}

export interface PastLanding {
  name: string
  lat: number
  lon: number
  source_url: string
}

// features.json: place names for the globe. Labels only; never used in a calculation.
export interface MoonFeatures {
  source: string
  names: MoonName[]
  landings: PastLanding[]
}

export interface PeriodStats {
  pct_sun: number
  pct_earth: number
  pct_both: number
  max_sun_gap_h: number
  max_earth_gap_h: number
}

export interface MonthStats extends PeriodStats {
  month: string
}

export interface CalendarYearStats extends PeriodStats {
  year: number
}

// A site's headline numbers by month and by calendar year. The pipeline writes one file per year,
// `<site>/year-<year>.json`; the app joins the years it has loaded into one of these.
export interface YearSummary {
  default_month: string
  // Every month of every year held, in order.
  months: MonthStats[]
  years: CalendarYearStats[]
}

// What span of time the data covers: `range.json`, the same size however long the range is.
// `start` is the first hour and `end` the hour after the last; both years are whole calendar years.
export interface DataRange {
  start: string
  end: string
  hours: number
  first_year: number
  last_year: number
  default_month: string
}

// When the Sun and Earth are up at every curated site, as the app works with it: each list is
// [from, to, from, to, ...] in hours after `start`, with `to` exclusive. The pipeline writes one
// file per calendar year (OverviewYear); the app joins the years it has loaded into one of these.
export interface Overview {
  start: string
  hours: number
  obs_height_m: number
  sites: Record<
    string,
    {
      sun: number[]
      earth: number[]
      // When Earth's center is at least this many degrees above the terrain, keyed by degrees.
      earth_above: Record<string, number[]>
    }
  >
}

// One calendar year of Overview, as the pipeline writes it: `overview/<year>.json`. The same
// shape, but each list is steps from `start`, the year's first hour: the hours before the first
// run, then each run's length and each gap's length in turn. Adding them up gives Overview's
// [from, to, ...]. A run that carries on past New Year ends at the year's last hour here.
export type OverviewYear = Overview

// One site's headline numbers per calendar year, at each height above the ground.
export interface MastHeight {
  obs_height_m: number
  years: CalendarYearStats[]
}

// How much a ridge site's numbers change within a landing's reach, and with NASA's terrain error.
export interface SpreadRow {
  pct_sun: [number, number]
  pct_earth: [number, number]
  pct_both: [number, number]
  max_sun_gap_h: [number, number]
  max_earth_gap_h: [number, number]
}

export interface ErrorStats {
  mean: number
  sd: number
  low: number
  high: number
}

export interface SiteSpread {
  radius_m: number
  step_m: number
  n_points: number
  terrain_resolution_m: number
  obs_height_m: number
  months: (SpreadRow & { month: string })[]
  years: (SpreadRow & { year: number })[]
  // The same site across NASA's clones of the 5 m terrain, over 18.6 years, at the exact point.
  terrain_error: {
    n_clones: number
    span: { start: string; end: string; step_h: number }
    by_height: { obs_height_m: number; sun_any_pct: ErrorStats; earth_any_pct: ErrorStats }[]
  }
}

export interface LrocAgreement {
  n: number
  bias: number
  rmse: number
  r: number
}

// The model and NASA's maps compared with LROC's map made from real photos of sunlight.
export interface LrocCheck {
  map: string
  period: { start: string; end: string; step_h: number }
  samples: {
    all_ground: { ours_ground: LrocAgreement; ours_2m: LrocAgreement; nasa_map: LrocAgreement }
    well_lit: { ours_ground: LrocAgreement; ours_2m: LrocAgreement; nasa_map: LrocAgreement }
  }
  // One 100 m photo pixel at each ridge site, with the model across that same pixel.
  sites: Record<
    string,
    { photo_pct: number; ours_ground_pct: number; ours_2m_pct: number; nasa_map_pct: number }
  >
}

// How the model's lit or dark call compares with one group of dated LROC photos, in percent.
export interface LrocPhotoScore {
  n_frames: number
  photo_lit_pct: number
  model_lit_pct: number
  // Lit and dark photos count equally. Null when the photos are all one kind.
  balanced_agreement_pct: number | null
  // The same score with the Sun half a month out of step.
  wrong_sun_agreement_pct: number | null
  // Middle 95% when frames are redrawn at random.
  interval_pct: [number, number] | null
}

export interface LrocPhotoHeight {
  // Every photo, split at the brightness that best matches LROC's own map.
  fitted: LrocPhotoScore
  // Only photos clearly dark or clearly lit.
  clear: LrocPhotoScore
  // Every photo, split at each of several other brightnesses.
  by_threshold: (LrocPhotoScore & { threshold: number })[]
}

// The model compared with individual dated LROC photos: was the ground lit at that moment?
// Measured by scripts/check_lroc_photos.py, outside the main build.
export interface LrocPhotos {
  frames_sampled: number
  first: string
  last: string
  // How many well_lit and all_ground spots were sampled, each.
  control_pixels: number
  threshold: number
  clearly_dark_below: number
  clearly_lit_from: number
  groups: Record<string, { ground: LrocPhotoHeight; up_2m: LrocPhotoHeight }>
}

// How a nearby-ground map compares with NASA's long-run maps, in percentage points.
export interface NearbyCheck {
  n: number
  bias: number
  rmse: number
  rank_r: number
  // The spots this model rates in its top 10%: their average here and on NASA's map, the
  // difference, and where they fall among all the sampled spots on NASA's map (percentile).
  top_ours: number
  top_map: number
  top_bias: number
  top_map_percentile: number
}

// A map of the ground around a site, on a square grid in polar stereographic x/y (m). Rows run from
// +y to -y and columns from -x to +x; the middle cell is the site. Each <month>.bin.gz holds whole
// percent Sun, Earth and both (one byte per cell each), then the longest Sun gap (little-endian
// uint16 hours). slope.bin.gz holds one byte per cell, in steps of slope_quant_deg.
export interface NearbyMeta {
  site_id: string
  half_width_m: number
  step_m: number
  size: number
  center_x_m: number
  center_y_m: number
  // The cell in the first row and column, as a check on the projection.
  corner: { lat: number; lon: number }
  slope_baseline_m: number
  slope_quant_deg: number
  obs_height_m: number
  check: {
    span: { start: string; end: string; step_h: number }
    map_resolution_m: number
    uniform: { sun: NearbyCheck; earth: NearbyCheck }
    well_lit: { sun: NearbyCheck; earth: NearbyCheck }
  }
}

// The point on Earth with the Sun straight overhead, for each hour of one month (degrees).
export interface EarthSunMonth {
  sub_lat: number[]
  sub_lon: number[]
}

export interface SpotCheck {
  body: string
  t: string
  our_az: number
  our_el: number
  horizons_az: number
  horizons_el: number
  sep_deg: number
}

export interface LongRunStats {
  obs_height_m: number
  sun_mean_disk_pct: number
  sun_any_pct: number
  earth_any_pct: number
}

export interface GridStats {
  quantity: string
  obs_height_m: number
  sample: string
  n: number
  bias: number
  median: number
  mae: number
  rmse: number
  r: number
}

export interface Validation {
  terrain_resolution_m: number
  horizons: { checks: SpotCheck[]; max_sep_deg: number }
  pgda: {
    span: { start: string; end: string; step_h: number }
    // Null where NASA's polar maps don't reach this latitude.
    map: {
      resolution_m: number
      sun_pct: number
      earth_pct: number
      sun_nearby_pct: [number, number]
      earth_nearby_pct: [number, number]
    } | null
    ours: LongRunStats[]
    grid: { step_h: number; high_sun_pct: number; stats: GridStats[] }
  }
  horizon_range: { range_km: number; max_diff_deg: number }[]
}
"""


def iso(t: np.datetime64) -> str:
    """ISO-8601 UTC string with a trailing ``Z``, to the second."""
    return f"{np.datetime64(t, 's')}Z"


def site_row(
    site: Site,
    slope_deg: float | None = None,
    slope_baseline_m: float | None = None,
    nearby_half_m: float | None = None,
    slope_err_deg: float | None = None,
) -> dict[str, Any]:
    """One ``sites.json`` entry; the slope and nearby map are left out where there are none."""
    row: dict[str, Any] = {
        "id": site.id,
        "name": site.name,
        "lat": site.lat_deg,
        "lon": site.lon_deg,
        "source_url": site.source_url,
        "group": site.group,
    }
    if slope_deg is not None:
        row["slope"] = {"deg": round(slope_deg, 1), "baseline_m": slope_baseline_m}
        if slope_err_deg is not None:
            row["slope"]["err_deg"] = round(slope_err_deg, 1)
    if nearby_half_m is not None:
        row["nearby_half_m"] = nearby_half_m
    return row


def horizon_rows(mask: HorizonMask) -> list[dict[str, float]]:
    """``horizon.json`` rows, angles rounded to 0.01°."""
    return [
        {"az": round(float(a), 2), "el": round(float(e), 2)}
        for a, e in zip(mask.az_deg, mask.el_deg, strict=True)
    ]


def track_rows(obs: Observation) -> list[dict[str, Any]]:
    """``track.json`` rows, angles rounded to 0.01°."""
    return [
        {
            "t": iso(obs.times[i]),
            "sun_az": round(float(obs.sun.az_deg[i]), 2),
            "sun_el": round(float(obs.sun.el_deg[i]), 2),
            "sun_frac": round(float(obs.sun_frac[i]), 3),
            "sun_up": bool(obs.sun_frac[i] > 0),
            "earth_az": round(float(obs.earth.az_deg[i]), 2),
            "earth_el": round(float(obs.earth.el_deg[i]), 2),
            "earth_up": bool(obs.earth_frac[i] > 0),
            "sun_vec_me": [round(float(c), 5) for c in obs.sun.unit_me[i]],
        }
        for i in range(len(obs.times))
    ]


def summary_dict(
    summary: Summary, start: np.datetime64, end: np.datetime64, step_h: int, obs_height_m: float
) -> dict[str, Any]:
    """``summary.json`` content; percentages rounded to 0.1, gaps in hours."""
    return {
        "range": {"start": iso(start), "end": iso(end), "step_h": step_h},
        "obs_height_m": obs_height_m,
        "pct_sun": round(summary.pct_sun, 1),
        "pct_earth": round(summary.pct_earth, 1),
        "pct_both": round(summary.pct_both, 1),
        "max_sun_gap_h": summary.max_sun_gap_h,
        "max_earth_gap_h": summary.max_earth_gap_h,
        "sun_windows": _windows(summary.sun_windows),
        "earth_windows": _windows(summary.earth_windows),
    }


def period_stats(summary: Summary) -> dict[str, float]:
    """Headline numbers for one period; percentages rounded to 0.1, gaps in hours."""
    return {
        "pct_sun": round(summary.pct_sun, 1),
        "pct_earth": round(summary.pct_earth, 1),
        "pct_both": round(summary.pct_both, 1),
        "max_sun_gap_h": summary.max_sun_gap_h,
        "max_earth_gap_h": summary.max_earth_gap_h,
    }


def year_dict(
    months: dict[str, Summary], years: dict[int, Summary], default_month: str
) -> dict[str, Any]:
    """``year-<year>.json`` content: headline numbers for each month of a year and for the year.

    One file per calendar year, so a page loads the years it shows and not the whole range.
    """
    return {
        "default_month": default_month,
        "months": [{"month": m} | period_stats(s) for m, s in months.items()],
        "years": [{"year": y} | period_stats(s) for y, s in years.items()],
    }


def runs(up: NDArray[np.bool_]) -> list[int]:
    """Where flags are true, as ``[from, to, from, to, ...]`` sample indices, ``to`` exclusive."""
    edges = np.flatnonzero(np.diff(np.concatenate(([False], up, [False])).astype(np.int8)))
    return [int(edge) for edge in edges]


def run_steps(up: NDArray[np.bool_]) -> list[int]:
    """Where flags are true, as steps: the hours before the first run, then each run's length and
    each gap's length in turn. Adding them up gives ``runs``. The numbers are shorter than
    positions, which makes the file a third smaller once compressed.
    """
    edges = runs(up)
    return edges[:1] + [after - before for before, after in zip(edges, edges[1:], strict=False)]


def clearance_key(clearance_deg: float) -> str:
    """The key for an Earth clearance in JSON: "2", not "2.0"."""
    return f"{clearance_deg:g}"


def overview_dict(
    start: np.datetime64,
    hours: int,
    obs_height_m: float,
    sites: dict[str, tuple[NDArray[np.bool_], NDArray[np.bool_], dict[float, NDArray[np.bool_]]]],
) -> dict[str, Any]:
    """``overview/<year>.json`` content: a year's hourly Sun and Earth up-times at every site.

    Each list is steps (``run_steps``) from ``start``, the year's first hour. One file per calendar
    year, so a page loads the years it shows; a run that crosses New Year is cut there and joined
    again on reading.
    """
    return {
        "start": iso(start),
        "hours": hours,
        "obs_height_m": obs_height_m,
        "sites": {
            site_id: {
                "sun": run_steps(sun),
                "earth": run_steps(earth),
                "earth_above": {clearance_key(k): run_steps(v) for k, v in above.items()},
            }
            for site_id, (sun, earth, above) in sites.items()
        },
    }


def range_dict(
    start: np.datetime64, hours: int, years: tuple[int, ...], default_month: str
) -> dict[str, Any]:
    """``range.json`` content: what span of time the data covers, the same size however long it is.

    Everything in the app that needs the first or last hour, or the list of years, reads it here.
    """
    return {
        "start": iso(start),
        "end": iso(start + np.timedelta64(hours, "h")),
        "hours": hours,
        "first_year": years[0],
        "last_year": years[-1],
        "default_month": default_month,
    }


def mast_heights_rows(by_height: dict[float, dict[int, Summary]]) -> list[dict[str, Any]]:
    """``heights.json`` content: a site's yearly numbers at each height above the ground."""
    return [
        {
            "obs_height_m": height_m,
            "years": [{"year": y} | period_stats(s) for y, s in years.items()],
        }
        for height_m, years in by_height.items()
    ]


def earth_sun_month(sub_lat_deg: NDArray[np.float64], sub_lon_deg: NDArray[np.float64]) -> dict:
    """One ``earth-sun/<month>.json``: hourly point with the Sun overhead, rounded to 0.01°."""
    return {
        "sub_lat": [round(float(v), 2) for v in sub_lat_deg],
        "sub_lon": [round(float(v), 2) for v in sub_lon_deg],
    }


def write_json(path: Path, content: object) -> None:
    """Write compact JSON, creating parent directories."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(content, separators=(",", ":")) + "\n")


def write_json_gz(path: Path, content: object) -> None:
    """Write the same compact JSON as ``write_json``, gzipped, at ``path`` with ``.gz`` added.

    For files that live in the assets bucket, where nothing compresses them on the way out: the
    page unpacks the gzip itself, as it does a terrain tile. Identical content gives identical
    bytes.
    """
    text = json.dumps(content, separators=(",", ":")) + "\n"
    write_bytes(path.with_name(path.name + ".gz"), gzip.compress(text.encode(), 6, mtime=0))


def write_bytes(path: Path, content: bytes) -> None:
    """Write a binary file, creating parent directories."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)


def write_contract(path: Path) -> None:
    """Write the TypeScript types for the JSON contract."""
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(CONTRACT_TS)


def _windows(windows: list[Window]) -> list[dict[str, str]]:
    return [{"start": iso(w.start), "end": iso(w.end)} for w in windows]
